//更改接口
function $$(i){		
if(i==$.c){
		return login('【无法选中提示】\n\n\n　　正在使用此接口，无需更换');
	}
else{
		$.d = i
		login('【确定选择提示】\n\n\n　　确定选择 【'+u[i][0]+'】 为当前搜索接口吗？\n\n\n　　点击下方 【确定启用】 按钮启用')
		return setv($)
	}
}
//确定更改
function yes(){
if($.c!=$.d){
		$.c=$.d
		$.a=u[$.c][1]
		$.b='https://res.'+$.a+'/'
		login('【接口启用提示】\n\n\n　　启用成功，已选择 【'+u[$.c][0]+'】 为当前搜索接口')
		return setv($)
	}
}


